/* Hand-written prose for the platform documentation, keyed by registry ids.
   The registry (registry.ts) is the source of truth for WHAT exists. This file only explains it.
   Anything in the registry without an entry here is listed on the docs page with a "Needs documentation" badge
   and fails `pnpm docs:check`. Entries here whose id no longer exists in the registry are reported as orphaned prose.
   Keep statements factual: describe what the code does today, and put known gaps under `limits`. */
import type { Perm } from '../pages/admin/roles'

export const DOCS_VERSION = '1.0'

/* ---------- Modules ---------- */
export type ModuleDoc = {
  what: string
  useCases?: string[]
  /** Optional (soft) dependencies: the module works alone but is better with these. Ids are validated. */
  optional?: string[]
  limits?: string[]
}

