/* ---------- Processes and flows ---------- */
export type FlowStep = { title: string; detail: string; actor?: string }
export type FlowFacts = 'dunning' | 'health' | 'approval' | 'documents' | 'tasks' | 'statuses' | 'changeAreas'
export type FlowDoc = {
  id: string
  title: string
  summary: string
  /** Billing module ids this flow touches. Validated against the registry. */
  modules: string[]
  roles: string[]
  steps: FlowStep[]
  states?: string[]
  routes?: string[]
  storage?: string[]
  limits?: string[]
  facts?: FlowFacts[]
}

